#include "dei_ask_private.h"
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/
#define DEI_ASK_OPEN_WINDOW         256
#define DEI_ASK_RESYNC_WINDOW       32767
#define DEI_ASK_RESYNC_COUNT        2
#define DEI_ASK_RESYNC_TIMEOUT      30000
/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

//--------------------------------------------------------------------------//

void dei_ask_database_init(void)
{
    dei_ask_nvfs_init();
    
    // --- create the sync count objects
    {
        UInt8 i ;
        
        for(i = 0 ; i < DEI_ASK_MAX_REMOTES ; i++)
        {
            dei_ask.sync_count_obj[i] = sync_count_create( DEI_ASK_OPEN_WINDOW   , 
                                                           DEI_ASK_RESYNC_WINDOW , 
                                                           DEI_ASK_RESYNC_COUNT  , 
                                                           DEI_ASK_RESYNC_TIMEOUT ) ; 
            
            
            sync_count_update( dei_ask.sync_count_obj[i] , dei_ask.database.remote[i].sync_count); 
        }
    }
}

